import{_ as n,C as r,o as c,c as h,j as e,a as d,E as o,a5 as i}from"./chunks/framework.CyyS6Zdm.js";const g=JSON.parse('{"title":"无限滚动","description":"","frontmatter":{},"headers":[],"relativePath":"components/infinite-scroll.md","filePath":"components/infinite-scroll.md","lastUpdated":1787173379000}'),s={name:"components/infinite-scroll.md"},b={id:"无限滚动",tabindex:"-1"};function p(u,t,f,q,x,m){const l=r("Badge"),a=r("XhDemo");return c(),h("div",null,[e("h1",b,[t[0]||(t[0]=d("无限滚动 ",-1)),o(l,{type:"info",text:"infinite-scroll"}),t[1]||(t[1]=d()),t[2]||(t[2]=e("a",{class:"header-anchor",href:"#无限滚动","aria-label":'Permalink to "无限滚动 <Badge type="info" text="infinite-scroll" />"'},"​",-1))]),t[3]||(t[3]=i('<p>滚到接近底部时触发一次加载。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>时间流、消息列表这类用户只关心&quot;再来一些&quot;的内容。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>用户需要跳到确定位置或分享某一页：用<a href="./pagination">分页</a>。</li><li>页面有页脚需要够得着：无限滚动会让页脚永远追不上。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li><code>distance</code> 是提前量：距底部还有这么远就触发，用户感觉不到等待。</li><li><code>loading</code> 与 <code>disabled</code> 由组件交给宿主，加载提示与结束语都由宿主自己摆。</li><li>取完之后关掉即可，不会再触发。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>哨兵滚进可视区就派 load，取完把 loading 写回 false</p>',10)),o(a,{src:"infinite-scroll/01-basic"}),t[4]||(t[4]=e("h3",{id:"提前量",tabindex:"-1"},[d("提前量 "),e("a",{class:"header-anchor",href:"#提前量","aria-label":'Permalink to "提前量"'},"​")],-1)),t[5]||(t[5]=e("p",null,"distance 把可视区沿块轴向外扩，哨兵还没露头就先取下一页",-1)),o(a,{src:"infinite-scroll/02-distance"}),t[6]||(t[6]=e("h3",{id:"取到没有了",tabindex:"-1"},[d("取到没有了 "),e("a",{class:"header-anchor",href:"#取到没有了","aria-label":'Permalink to "取到没有了"'},"​")],-1)),t[7]||(t[7]=e("p",null,"最后一页取完把 disabled 打开，哨兵不再被观察，load 也不再派",-1)),o(a,{src:"infinite-scroll/03-disabled"}),t[8]||(t[8]=e("h3",{id:"状态透出",tabindex:"-1"},[d("状态透出 "),e("a",{class:"header-anchor",href:"#状态透出","aria-label":'Permalink to "状态透出"'},"​")],-1)),t[9]||(t[9]=e("p",null,"phase / loading / disabled 由组件交给宿主，加载提示与结束语都由宿主自己摆",-1)),o(a,{src:"infinite-scroll/04-slot-state"}),t[10]||(t[10]=i('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-infinite-scroll&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhInfiniteScrollRoot</code> <code>XhInfiniteScrollSentinel</code></td></tr><tr><td>组合式函数</td><td><code>useInfiniteScroll</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/infinite-scroll.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;infinite-scroll&quot;</code>：<strong><code>root</code></strong> · <strong><code>sentinel</code></strong></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>distance</code></td><td><code>number</code></td><td></td><td>提前量（px）：哨兵离可视区还有这么远就算进入，默认 0（真正露头才算）。扩的是 getTargetEl 给出的那块可视区。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>关掉：不再观察，也不再触发。列表已经没有下一页时用它。</td></tr><tr><td><code>loading</code></td><td><code>boolean</code></td><td></td><td>正在取数：其间不观察、不重复触发。取完由宿主写回 false。</td></tr><tr><td><code>onLoad</code></td><td><code>() =&gt; void</code></td><td></td><td>该取下一页了。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>load</code></td><td>``</td><td>该取下一页了</td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhInfiniteScrollRoot</code></td><td><code>default</code></td><td><code>InfiniteScrollRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>root</code></td><td>state.get()</td></tr><tr><td><code>sentinel</code></td><td>state.get()</td></tr></tbody></table><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>事件</strong>：<code>SENTINEL.ENTER</code> · <code>MODE.SYNC</code></p><p><strong>判据</strong>：<code>isPaused</code> · <code>isLoading</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useInfiniteScroll</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>phase</code></td><td><code>InfiniteScrollPhase</code></td><td></td></tr><tr><td><code>loading</code></td><td><code>boolean</code></td><td>正在取数。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td>已关掉，不再观察。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getSentinelProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-busy</code></td><td>&#39;true&#39; | undefined</td></tr><tr><td><code>sentinel</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/infinite-scroll.css</code> 按部件选择：<code>[data-scope=&quot;infinite-scroll&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-loading</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-state</code></td><td>state.get()</td></tr><tr><td><code>sentinel</code></td><td><code>data-state</code></td><td>state.get()</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-infinite-scroll-sentinel-size</code></p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>与<a href="./list">列表</a>、<a href="./virtualizer">虚拟滚动</a>、<a href="./skeleton">骨架屏</a>配合。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>明确的结束提示：&quot;没有更多了&quot;比无声停止好。</li><li>加载失败要能重试，别静默停在那里。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>页面底部有重要内容（页脚、版权、联系方式）却用无限滚动。</li><li>不给结束提示，用户一直往下滚。</li></ul>',42))])}const k=n(s,[["render",p]]);export{g as __pageData,k as default};
